        ("title_case", "Write a function `title(s)` capitalizing the first letter of every word and lowercasing the rest (words split by spaces).", ["assert title('hello wORLD') == 'Hello World'", "assert title('a') == 'A'"], "def title(s):\n    return ' '.join(w[:1].upper()+w[1:].lower() for w in s.split(' '))"),
        ("flatten", "Write a function `flatten(xs)` flattening a list of lists one level deep into a single list.", ["assert flatten([[1,2],[3],[]]) == [1,2,3]", "assert flatten([]) == []"], "def flatten(xs):\n    return [y for x in xs for y in x]"),
        ("unique_order", "Write a function `uniq(xs)` removing duplicates from a list while keeping the first occurrence order.", ["assert uniq([3,1,3,2,1]) == [3,1,2]", "assert uniq([]) == []"], "def uniq(xs):\n    seen=set(); out=[]\n    for x in xs:\n        if x not in seen: seen.add(x); out.append(x)\n    return out"),
