        ("merge_deep", "Write a function `merge(a, b)` deep-merging two dicts: values from b win, nested dicts are merged recursively, inputs are not mutated.", ["a={'x':{'y':1,'z':2},'k':1}; b={'x':{'y':9},'m':3}", "assert merge(a,b) == {'x':{'y':9,'z':2},'k':1,'m':3}", "assert a == {'x':{'y':1,'z':2},'k':1}"], "import copy\ndef merge(a,b):\n    o=copy.deepcopy(a)\n    for k,v in b.items():\n        if isinstance(v,dict) and isinstance(o.get(k),dict): o[k]=merge(o[k],v)\n        else: o[k]=copy.deepcopy(v)\n    return o"),
        ("sort_records", "Write a function `sort_records(rows)` sorting a list of dicts by 'age' descending and then by 'name' ascending.", ["r=[{'name':'b','age':30},{'name':'a','age':30},{'name':'c','age':40}]", "assert [x['name'] for x in sort_records(r)] == ['c','a','b']"], "def sort_records(rows):\n    return sorted(rows,key=lambda r:(-r['age'],r['name']))"),
        ("csv_to_json", "Write a function `csv_to_records(text)` parsing CSV text whose first line is the header into a list of dicts (all values strings). Use the csv module.", ["t='name,age\\nann,30\\nbob,25\\n'", "assert csv_to_records(t) == [{'name':'ann','age':'30'},{'name':'bob','age':'25'}]", "assert csv_to_records('a,b\\n') == []"], "import csv,io\ndef csv_to_records(t):\n    return list(csv.DictReader(io.StringIO(t)))"),
        ("count_by", "Write a function `count_by(items, key)` counting how many dicts in the list have each value of `key`; dicts without the key are skipped.", ["assert count_by([{'t':'a'},{'t':'b'},{'t':'a'},{}], 't') == {'a':2,'b':1}"], "def count_by(items,key):\n    o={}\n    for i in items:\n        if key in i: o[i[key]]=o.get(i[key],0)+1\n    return o"),
