        ("dedupe_records", "Write a function `dedupe(rows, key)` removing dicts that repeat the value of `key`, keeping the first one, order preserved.", ["r=[{'id':1,'v':'a'},{'id':2,'v':'b'},{'id':1,'v':'c'}]", "assert dedupe(r,'id') == [{'id':1,'v':'a'},{'id':2,'v':'b'}]"], "def dedupe(rows,key):\n    s=set();o=[]\n    for r in rows:\n        if r[key] not in s: s.add(r[key]); o.append(r)\n    return o"),
