# ------------------------------------------------------------------ hard: multi-function
def hard_custom() -> None:
    H = [
        ("lru", "Write a class `LRU` with `__init__(self, capacity)`, `get(key)` returning the value or -1, and `put(key, value)`. When over capacity the least recently used key is evicted; both get and put count as use. Both operations must be O(1).",
         ["c=LRU(2)", "c.put(1,1); c.put(2,2)", "assert c.get(1) == 1", "c.put(3,3)", "assert c.get(2) == -1", "c.put(4,4)", "assert c.get(1) == -1 and c.get(3) == 3 and c.get(4) == 4", "c.put(3, 30)", "assert c.get(3) == 30"],
         "from collections import OrderedDict\nclass LRU:\n    def __init__(self,c): self.c=c; self.d=OrderedDict()\n    def get(self,k):\n        if k not in self.d: return -1\n        self.d.move_to_end(k); return self.d[k]\n    def put(self,k,v):\n        self.d[k]=v; self.d.move_to_end(k)\n        if len(self.d)>self.c: self.d.popitem(last=False)"),
        ("calc", "Write a function `calc(expr)` evaluating an arithmetic expression string with integers, + - * /, parentheses and unary minus, respecting precedence. Do not use eval. Division is true division. Spaces may appear anywhere.",
         ["assert calc('1 + 2 * 3') == 7", "assert calc('(1 + 2) * 3') == 9", "assert calc('-4 + 10 / 4') == -1.5", "assert calc('2 * (3 + (4 - 1)) * -1') == -12", "assert calc('42') == 42"],
         "def calc(s):\n    import re\n    t=re.findall(r'\\d+|[-+*/()]',s); i=0\n    def peek():\n        return t[i] if i<len(t) else None\n    def expr():\n        nonlocal i\n        v=term()\n        while peek() in ('+','-'):\n            o=t[i]; i+=1; r=term(); v=v+r if o=='+' else v-r\n        return v\n    def term():\n        nonlocal i\n        v=unary()\n        while peek() in ('*','/'):\n            o=t[i]; i+=1; r=unary(); v=v*r if o=='*' else v/r\n        return v\n    def unary():\n        nonlocal i\n        if peek()=='-': i+=1; return -unary()\n        if peek()=='(':\n            i+=1; v=expr(); i+=1; return v\n        v=int(t[i]); i+=1; return v\n    return expr()"),
        ("intervals", "Write two functions: `merge(intervals)` merging overlapping or touching closed intervals given as a list of [start, end] pairs and returning them sorted, and `free_slots(intervals, day_start, day_end)` returning the gaps (as [start, end] pairs) inside [day_start, day_end] not covered by any interval, using merge.",
         ["assert merge([[1,3],[2,6],[8,10],[6,7]]) == [[1,7],[8,10]]", "assert merge([]) == []", "assert free_slots([[9,10],[12,13]], 8, 17) == [[8,9],[10,12],[13,17]]", "assert free_slots([[8,17]], 8, 17) == []", "assert free_slots([], 8, 17) == [[8,17]]"],
         "def merge(iv):\n    o=[]\n    for s,e in sorted(iv):\n        if o and s<=o[-1][1]: o[-1][1]=max(o[-1][1],e)\n        else: o.append([s,e])\n    return o\ndef free_slots(iv,a,b):\n    o=[];c=a\n    for s,e in merge(iv):\n        if s>c: o.append([c,s])\n        c=max(c,e)\n    if c<b: o.append([c,b])\n    return o"),
        ("matrix", "Write three functions on matrices given as lists of lists: `mat_mul(a, b)` (matrix product), `mat_transpose(m)`, and `mat_pow(m, k)` (square matrix to the integer power k >= 0 using repeated squaring; k=0 gives the identity).",
         ["assert mat_mul([[1,2],[3,4]], [[5,6],[7,8]]) == [[19,22],[43,50]]", "assert mat_transpose([[1,2,3]]) == [[1],[2],[3]]", "assert mat_pow([[1,1],[1,0]], 10) == [[89,55],[55,34]]", "assert mat_pow([[2,0],[0,2]], 0) == [[1,0],[0,1]]"],
         "def mat_mul(a,b):\n    return [[sum(x*y for x,y in zip(r,c)) for c in zip(*b)] for r in a]\ndef mat_transpose(m):\n    return [list(r) for r in zip(*m)]\ndef mat_pow(m,k):\n    n=len(m); r=[[int(i==j) for j in range(n)] for i in range(n)]\n    while k:\n        if k&1: r=mat_mul(r,m)\n        m=mat_mul(m,m); k>>=1\n    return r"),
        ("inventory", "Write a class `Inventory` with add(item, qty), remove(item, qty) (raises ValueError if stock is insufficient or the item is unknown), stock(item) (0 if unknown), low(threshold) (sorted list of items with stock strictly below threshold) and a history list of (op, item, qty) tuples recording every successful add/remove in order.",
         ["i=Inventory()", "i.add('a',5); i.add('b',1); i.add('a',2)", "assert i.stock('a') == 7 and i.stock('z') == 0", "i.remove('a',3)", "assert i.stock('a') == 4", "try:\n    i.remove('a',10)\n    assert False\nexcept ValueError:\n    pass", "try:\n    i.remove('q',1)\n    assert False\nexcept ValueError:\n    pass", "assert i.low(3) == ['b']", "assert i.history == [('add','a',5),('add','b',1),('add','a',2),('remove','a',3)]"],
         "class Inventory:\n    def __init__(self): self.s={}; self.history=[]\n    def add(self,i,q): self.s[i]=self.s.get(i,0)+q; self.history.append(('add',i,q))\n    def remove(self,i,q):\n        if self.s.get(i,0)<q: raise ValueError\n        self.s[i]-=q; self.history.append(('remove',i,q))\n    def stock(self,i): return self.s.get(i,0)\n    def low(self,t): return sorted(k for k,v in self.s.items() if v<t)"),
        ("topo", "Write a function `build_order(deps)` taking a dict mapping each task to the list of tasks it depends on, and returning a list of all tasks in a valid execution order (dependencies first; ties broken alphabetically so the result is deterministic). Raise ValueError on a cycle. Tasks that only appear as dependencies must be included.",
         ["assert build_order({'a':['b','c'],'b':['c'],'c':[]}) == ['c','b','a']", "assert build_order({'x':['y']}) == ['y','x']", "assert build_order({}) == []", "try:\n    build_order({'a':['b'],'b':['a']})\n    assert False\nexcept ValueError:\n    pass", "assert build_order({'b':[],'a':[]}) == ['a','b']"],
         "def build_order(deps):\n    import heapq\n    nodes=set(deps)|{d for v in deps.values() for d in v}\n    indeg={n:0 for n in nodes}; out={n:[] for n in nodes}\n    for n,v in deps.items():\n        for d in set(v): indeg[n]+=1; out[d].append(n)\n    h=[n for n in nodes if indeg[n]==0]; heapq.heapify(h); r=[]\n    while h:\n        n=heapq.heappop(h); r.append(n)\n        for m in out[n]:\n            indeg[m]-=1\n            if indeg[m]==0: heapq.heappush(h,m)\n    if len(r)!=len(nodes): raise ValueError\n    return r"),
    ]
    for name, desc, tests, ref in H:
        add(f"multi-{name}", "hard", desc, tests, ref)


# ------------------------------------------------------------------ HumanEval / MBPP
def from_datasets() -> None:
    he, mb = fetch.all_rows("humaneval"), fetch.all_rows("mbpp")
    items = []
    for r in he:
        items.append({"id": r["task_id"].replace("/", "-").lower(), "source": "humaneval",
                      "prompt": "Complete the following Python function. Reply with the complete function in one ```python code block.\n\n" + r["prompt"],
                      "grader": "unit_test", "data": {"kind": "humaneval", "prompt": r["prompt"], "test": r["test"], "entry_point": r["entry_point"]}, "_len": len(r["prompt"])})
    for r in mb:
        tests = r["test_list"]
        items.append({"id": f"mbpp-{r['task_id']}", "source": "mbpp",
                      "prompt": f"{r['prompt']}\nYour code must pass these tests:\n" + "\n".join(tests) + "\n\nReply with the Python code in one ```python code block.",
                      "grader": "unit_test", "data": {"kind": "mbpp", "imports": r["test_imports"], "tests": tests}, "_len": len(r["prompt"]) + sum(map(len, tests))})
    items.sort(key=lambda x: -x["_len"])
    n_hard = 80 - sum(r["difficulty"] == "hard" for r in rows)
    hard, rest = items[:n_hard], items[n_hard:]
    n_every = 120 - sum(r["difficulty"] == "everyday" for r in rows)
    pick = random.Random(20261114).sample(rest, n_every)
    for it, d in [(h, "hard") for h in hard] + [(p, "everyday") for p in pick]:
        it.pop("_len")
        rows.append({"id": it.pop("id"), "difficulty": d, **it})


def main() -> None:
    trivial(); everyday_custom(); hard_custom()
    bad = []
    for r in rows:  # reference solutions must pass their own tests
        if r["id"] in refs and not grade.grade(r, "```python\n" + refs[r["id"]] + "\n```"):
            bad.append(r["id"])
    if bad:
        raise SystemExit(f"reference solution fails its own tests: {bad}")
    from_datasets()
    ids = [r["id"] for r in rows]
    assert len(ids) == len(set(ids)), "duplicate ids"
    OUT.write_text("".join(json.dumps(r) + "\n" for r in rows))
    from collections import Counter
    print(Counter(r["difficulty"] for r in rows), len(rows), "-> tasks.jsonl;", len(refs), "custom tasks, references pass")


if __name__ == "__main__":
    main()
